type PreferencesValue = { language: AppLanguage; theme: ThemePreference; resolvedTheme: 'light' | 'dark'; setLanguage: (value: AppLanguage) => void; setTheme: (value: ThemePreference) => void; t: (key: string, params?: Params) => string };
const PreferencesContext = createContext<PreferencesValue | null>(null); const LANGUAGE_KEY = 'classio.interfaceLanguage'; const THEME_KEY = 'classio.themePreference';

export function AppPreferencesProvider({ children }: PropsWithChildren) {
  const [language, setLanguageState] = useState<AppLanguage>('en'); const [theme, setThemeState] = useState<ThemePreference>('auto'); const [systemTheme, setSystemTheme] = useState<'light' | 'dark'>(Appearance.getColorScheme() === 'dark' ? 'dark' : 'light');
  useEffect(() => { void Promise.all([AsyncStorage.getItem(LANGUAGE_KEY), AsyncStorage.getItem(THEME_KEY)]).then(([storedLanguage, storedTheme]) => { if (storedLanguage === 'en' || storedLanguage === 'es' || storedLanguage === 'tr') setLanguageState(storedLanguage); if (storedTheme === 'auto' || storedTheme === 'light' || storedTheme === 'dark') setThemeState(storedTheme); }); const subscription = Appearance.addChangeListener(({ colorScheme }) => setSystemTheme(colorScheme === 'dark' ? 'dark' : 'light')); return () => subscription.remove(); }, []);
  useEffect(() => { if (Platform.OS !== 'web' || typeof document === 'undefined') return; let style = document.getElementById('classio-theme-tokens') as HTMLStyleElement | null; if (!style) { style = document.createElement('style'); style.id = 'classio-theme-tokens'; style.textContent = classioThemeCss; document.head.appendChild(style); } document.documentElement.dataset.classioTheme = theme; document.documentElement.lang = language; }, [language, theme]);
  const setLanguage = (value: AppLanguage) => { setLanguageState(value); void AsyncStorage.setItem(LANGUAGE_KEY, value); }; const setTheme = (value: ThemePreference) => { setThemeState(value); void AsyncStorage.setItem(THEME_KEY, value); };
  const value = useMemo<PreferencesValue>(() => ({ language, theme, resolvedTheme: theme === 'auto' ? systemTheme : theme, setLanguage, setTheme, t: (key, params) => { const template = dictionaries[language][key] || en[key] || key; return Object.entries(params || {}).reduce((result, [name, replacement]) => result.replaceAll(`{${name}}`, String(replacement)), template); } }), [language, systemTheme, theme]);
  return <PreferencesContext.Provider value={value}>{children}</PreferencesContext.Provider>;
}
export function useAppPreferences() { const value = useContext(PreferencesContext); if (!value) throw new Error('useAppPreferences must be used inside AppPreferencesProvider.'); return value; }

